/**
 * Deterministic lead triage — a faithful port of the Python internal build
 * (veldway-demos/lead-intake-triage/rules.py). Every point of the score is
 * traceable to a rule; the model never decides the score or the category.
 * Parity with the Python original is pinned by test/rules.test.js against
 * fixtures generated by the Python implementation itself.
 */

export const REQUIRED_FIELDS = ["id", "received_at", "source", "name", "email", "company", "message"];

const URGENCY = /\b(urgent|asap|this week|today|deadline|by friday|right away|next two weeks|immediately)\b/i;
const FIT = /\b(shopify|klaviyo|liquid|theme|checkout|inventory|integration|automation|erp|sync|flows?|retention|crm)\b/gi;
const BUDGET = /(?:\$|usd\s?|eur\s?|£|€)\s?(\d[\d,]*(?:\.\d+)?)\s?(k\b)?/gi;
const REFERRAL_SOURCES = new Set(["referral", "partner", "introduction"]);
const SPAM_PHRASES = /\b(guaranteed|#1 google|backlinks?|seo blast|crypto payment|100% free|limited offer|act now)\b/i;
const LINK = /https?:\/\//gi;
const INJECTION = /\b(ignore (all )?(previous|prior|above) instructions?|disregard (the )?(previous|prior|above)|you are now|system prompt)\b/i;

export class InputError extends Error {}

export function validate(lead) {
  for (const field of REQUIRED_FIELDS) {
    if (!(field in lead)) {
      throw new InputError(`lead ${JSON.stringify(lead.id ?? "?")} is missing ${JSON.stringify(field)}`);
    }
  }
  if (!String(lead.message).trim()) {
    throw new InputError(`lead ${JSON.stringify(lead.id)} has an empty message`);
  }
}

/** Largest figure whose nearby text says budget/spend; else the largest figure. */
export function budgetAmount(message) {
  const nearBudget = [];
  const allFigures = [];
  for (const match of message.matchAll(BUDGET)) {
    let value = parseFloat(match[1].replaceAll(",", ""));
    if (match[2]) value *= 1000; // "3k" style
    allFigures.push(value);
    const context = message.slice(Math.max(0, match.index - 40), match.index).toLowerCase();
    if (context.includes("budget") || context.includes("spend")) nearBudget.push(value);
  }
  if (nearBudget.length) return Math.max(...nearBudget);
  return allFigures.length ? Math.max(...allFigures) : null;
}

const fmt = (n) => Math.round(n).toLocaleString("en-US");

/** Score one validated lead: {id, score, category, reasons, budget, injection_suspected}. */
export function triage(lead) {
  validate(lead);
  const message = String(lead.message);
  const reasons = [];
  let score = 0;

  // Spam and injection signals are judged first and disqualify.
  let spamPoints = 0;
  if (SPAM_PHRASES.test(message)) {
    spamPoints += 2;
    reasons.push("spam phrases in message");
  }
  if ((message.match(LINK) || []).length >= 3) {
    spamPoints += 1;
    reasons.push("3+ links in message");
  }
  if (!String(lead.name).trim()) {
    spamPoints += 1;
    reasons.push("no sender name");
  }
  const injection = INJECTION.test(message);
  if (injection) {
    spamPoints += 2;
    reasons.push("prompt-injection phrasing in message");
  }
  if (spamPoints >= 2) {
    return { id: lead.id, score: 0, category: "spam", reasons, budget: null, injection_suspected: injection };
  }

  const fitMatches = message.match(FIT);
  if (fitMatches && fitMatches.length) {
    const hits = [...new Set(fitMatches.map((m) => m.toLowerCase()))].sort();
    score += Math.min(30, 10 * hits.length);
    reasons.push("service fit: " + hits.join(", "));
  }
  if (URGENCY.test(message)) {
    score += 25;
    reasons.push("urgency language");
  }
  const budget = budgetAmount(message);
  if (budget !== null) {
    score += budget >= 1000 ? 25 : 10;
    reasons.push(`budget named (~${fmt(budget)})`);
  }
  if (REFERRAL_SOURCES.has(String(lead.source).toLowerCase())) {
    score += 20;
    reasons.push("came via referral");
  }
  if (message.length >= 120) {
    score += 5;
    reasons.push("substantive message");
  }

  const category = score >= 70 ? "hot" : score >= 40 ? "qualified" : "nurture";
  return { id: lead.id, score, category, reasons, budget, injection_suspected: injection };
}
